package com.bank.pattern.model;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class SavingsAccount extends Account {
    private final BigDecimal annualRate;

    public SavingsAccount(String id, BigDecimal balance, BigDecimal rate) {
        super(id, balance); this.annualRate = rate;
    }

    public BigDecimal calculateInterest() {
        return getBalance().multiply(annualRate).divide(BigDecimal.valueOf(12), 2, RoundingMode.HALF_UP);
    }
    public BigDecimal getAnnualRate() { return annualRate; }
}
