// ─── File: src/main/java/com/bank/pattern/service/AccountProcessor.java ───
package com.bank.pattern.service;

import com.bank.pattern.model.*;
import java.math.BigDecimal;
import java.util.*;

public class AccountProcessor {

    // ═══ OLD WAY: instanceof + explicit cast (pre-Java 16) ═══
    public String processOldWay(Account account) {
        if (account instanceof SavingsAccount) {
            SavingsAccount sa = (SavingsAccount) account;  // explicit cast — redundant!
            return "Savings interest: Rs." + sa.calculateInterest();
        } else if (account instanceof CurrentAccount) {
            CurrentAccount ca = (CurrentAccount) account;
            return "Current overdraft: Rs." + ca.getOverdraftLimit();
        }
        return "Unknown type";
    }

    // ═══ NEW WAY: pattern matching (Java 16+) ═══
    public String processNewWay(Account account) {
        if (account instanceof SavingsAccount sa) {
            // No cast! 'sa' is already SavingsAccount.
            return "Savings interest: Rs." + sa.calculateInterest();
        } else if (account instanceof CurrentAccount ca) {
            return "Current overdraft: Rs." + ca.getOverdraftLimit();
        } else if (account instanceof NRIAccount nri) {
            return "NRI currency: " + nri.getCurrency();
        }
        return "Unknown type";
    }

    // ═══ WITH GUARD (&&): ═══
    public String processWithGuard(Account account) {
        if (account instanceof SavingsAccount sa
            && sa.getBalance().compareTo(new BigDecimal("100000")) > 0) {
            return "PREMIUM Savings: " + sa.getAccountId() + " Rs." + sa.getBalance();
        } else if (account instanceof SavingsAccount sa) {
            return "Regular Savings: " + sa.getAccountId();
        } else if (account instanceof CurrentAccount ca) {
            return "Current: " + ca.getAccountId();
        }
        return "Other";
    }

    // ═══ SWITCH PATTERN MATCHING (Java 21) ═══
    public String processSwitch(Account account) {
        return switch (account) {
            case SavingsAccount sa when sa.getBalance().compareTo(new BigDecimal("100000")) > 0
                -> "Premium Savings: " + sa.getAccountId() + " Rs." + sa.getBalance()
                   + " (rate " + sa.getAnnualRate() + ")";
            case SavingsAccount sa
                -> "Regular Savings: " + sa.getAccountId();
            case CurrentAccount ca
                -> "Current: " + ca.getAccountId() + " (OD Rs." + ca.getOverdraftLimit() + ")";
            case NRIAccount nri
                -> "NRI: " + nri.getAccountId() + " (" + nri.getCurrency() + ")";
            case null
                -> "No account";
            default
                -> "Unknown: " + account.getClass().getSimpleName();
        };
    }

    // ═══ NEGATED INSTANCEOF — flow scoping in else ═══
    public BigDecimal getInterestOrZero(Account account) {
        if (!(account instanceof SavingsAccount sa)) {
            return BigDecimal.ZERO;  // not savings → zero interest
        }
        // Flow scoping: 'sa' IS available here — compiler knows instanceof passed
        return sa.calculateInterest();
    }

    // ═══ BATCH: process all accounts polymorphically with pattern matching ═══
    public List<String> processAll(List<Account> accounts) {
        return accounts.stream()
            .map(this::processSwitch)
            .toList();
    }
}
```

```java
// ─── File: src/test/java/com/bank/pattern/PatternMatchingTest.java ───
package com.bank.pattern;

import com.bank.pattern.model.*;
import com.bank.pattern.service.AccountProcessor;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.List;
import static org.assertj.core.api.Assertions.*;

class PatternMatchingTest {

    AccountProcessor processor = new AccountProcessor();

    Account savings = new SavingsAccount("SAV001", new BigDecimal("120000"), new BigDecimal("0.04"));
    Account current = new CurrentAccount("CUR001", new BigDecimal("500000"), new BigDecimal("100000"));
    Account nri = new NRIAccount("NRI001", new BigDecimal("2500000"), "USD");
    Account smallSavings = new SavingsAccount("SAV002", new BigDecimal("5000"), new BigDecimal("0.04"));

    @Test
    void oldAndNewWayProduceSameResult() {
        String oldResult = processor.processOldWay(savings);
        String newResult = processor.processNewWay(savings);
        assertThat(oldResult).isEqualTo(newResult);  // same output, cleaner code!
    }

    @Test
    void patternMatchingNoCastNeeded() {
        String result = processor.processNewWay(savings);
        assertThat(result).contains("Savings interest");

        result = processor.processNewWay(current);
        assertThat(result).contains("Current overdraft");

        result = processor.processNewWay(nri);
        assertThat(result).contains("NRI currency").contains("USD");
    }

    @Test
    void guardCondition_premiumVsRegular() {
        String premium = processor.processWithGuard(savings);  // 120000 > 100000
        String regular = processor.processWithGuard(smallSavings);  // 5000 < 100000

        assertThat(premium).contains("PREMIUM");
        assertThat(regular).contains("Regular");
    }

    @Test
    void switchPatternMatching() {
        assertThat(processor.processSwitch(savings)).contains("Premium Savings").contains("rate");
        assertThat(processor.processSwitch(smallSavings)).contains("Regular Savings");
        assertThat(processor.processSwitch(current)).contains("Current").contains("OD");
        assertThat(processor.processSwitch(nri)).contains("NRI").contains("USD");
        assertThat(processor.processSwitch(null)).isEqualTo("No account");
    }

    @Test
    void negatedInstanceof_flowScoping() {
        BigDecimal interest = processor.getInterestOrZero(savings);
        assertThat(interest).isGreaterThan(BigDecimal.ZERO);

        BigDecimal zero = processor.getInterestOrZero(current);
        assertThat(zero).isEqualByComparingTo("0");
    }

    @Test
    void batchProcessAllTypes() {
        List<String> results = processor.processAll(List.of(savings, current, nri, smallSavings));
        assertThat(results).hasSize(4);
        assertThat(results.get(0)).contains("Premium");
        assertThat(results.get(1)).contains("Current");
        assertThat(results.get(2)).contains("NRI");
        assertThat(results.get(3)).contains("Regular");
    }
}
```

sections.s5b_flow:
```
  ═══ BEFORE Java 16 (verbose, error-prone) ═══

  if (account instanceof SavingsAccount) {           ← step 1: check
      SavingsAccount sa = (SavingsAccount) account;  ← step 2: cast (redundant!)
      sa.calculateInterest();
  }
  // Risk: cast to WRONG type → ClassCastException at runtime!

  ═══ AFTER Java 16 (pattern matching) ═══

  if (account instanceof SavingsAccount sa) {  ← check + cast + bind in ONE step!
      sa.calculateInterest();                   ← no cast needed!
  }
  // No ClassCastException risk. Cleaner. Shorter.

  ═══ SWITCH PATTERN MATCHING (Java 21) ═══

  switch (account) {
      case SavingsAccount sa when sa.getBalance() > 100K → "Premium"
      case SavingsAccount sa                              → "Regular"
      case CurrentAccount ca                              → "Current"
      case NRIAccount nri                                 → "NRI"
      case null                                           → "null"
      default                                             → "Unknown"
  }
  // Type check + cast + bind + guard + exhaustive — all in switch!
```
